window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8465e0c81a3a105e"]={"versions": [{"id": "FIG-8465e0c81a3a105e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm spezifiziert die Modellstruktur zur Gruppierung und Kapselung von AUTOSAR-Modellelementen über Pakete und Sammlungen (<code>Collection</code>) im Metamodell.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Vererbung:</p>\n<ul class=\"fig-list\"><li><code>CollectableElement</code> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für alle sammelbaren Elemente.\n</li><li><code>ARPackage</code> (spezialisiert <code>CollectableElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>Identifiable</code>): Paketierungscontainer im Namensraum.\n</li><li><code>PackageableElement</code> (spezialisiert <code>CollectableElement</code>, <code>Identifiable</code>): Basisklasse für paketierbare Elemente.\n</li><li><code>ARElement</code> (spezialisiert <code>PackageableElement</code>): Top-Level-AUTOSAR-Element.\n</li><li><code>Collection</code> (spezialisiert <code>ARElement</code>): Gruppierungselement zur Zusammenfassung beliebiger sammelbarer Elemente.\n</li></ul>\n<p class=\"fig-p\">Assoziationen und Kompositionen:</p>\n<ul class=\"fig-list\"><li><code>ARPackage</code> enthält per Komposition <code>+arPackage</code> (<code>0..*</code>, <code>«atpSplitable,atpVariation»</code>) untergeordnete <code>ARPackage</code>-Instanzen.\n</li><li><code>ARPackage</code> enthält per Komposition <code>+element</code> (<code>0..*</code>, <code>«atpSplitable,atpVariation»</code>) Instanzen vom Typ <code>PackageableElement</code>.\n</li><li><code>Collection</code> referenziert über die gerichtete Assoziation <code>+element</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>CollectableElement</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die strukturelle Organisation und Referenzierung von Elementen innerhalb der Paket- und Sammlungs-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Strukturierung von ARXML-Beschreibungsdateien. <code>Collection</code> erlaubt als eigenständiges <code>ARElement</code> das Querreferenzieren und Bündeln beliebiger <code>CollectableElement</code>-Instanzen (inklusive Pakete und paketierbare Elemente) über Paketgrenzen hinweg. Die Kompositionen innerhalb von <code>ARPackage</code> sind als <code>«atpSplitable,atpVariation»</code> annotiert, was die Aufteilung über mehrere Dateien und variantenspezifische Ausprägungen gemäß AUTOSAR-Variantenhandhabung ermöglicht.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2832bafdff706200", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Es definiert die Metamodell-Struktur für AUTOSAR-Sammlungen (<code>Collection</code>), Instanzreferenzen (<code>AnyInstanceRef</code>) sowie Variantenmengen (<code>EvaluatedVariantSet</code>) im Kontext von Element- und Merkmalsreferenzierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Vererbung:</p>\n<ul class=\"fig-list\"><li><code>MultilanguageReferrable</code>: Basisklasse für mehrsprachig referenzierbare Elemente.\n</li><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für sammelbare Entitäten.\n</li><li><code>AtpFeature</code> (spezialisiert <code>Identifiable</code>): Repräsentiert referenzierbare Merkmale/Features im Metamodell.\n</li><li><code>PackageableElement</code> (spezialisiert <code>Identifiable</code>): Paketierbare Elemente.\n</li><li><code>ARPackage</code> (spezialisiert <code>CollectableElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>Identifiable</code>): Paketierungscontainer.\n</li><li><code>ARElement</code> (spezialisiert <code>PackageableElement</code>): Top-Level-AUTOSAR-Elemente.\n</li><li><code>Collection</code> (spezialisiert <code>ARElement</code>): Sammlungscontainer mit Attributen <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>.\n</li><li><code>EvaluatedVariantSet</code> (spezialisiert <code>ARElement</code>): Beschreibt evaluierte Varianten mit Attribut <code>approvalStatus: NameToken</code>.\n</li><li><code>AtpInstanceRef</code>: Abstrakte Basisklasse für Instanzreferenzen.\n</li><li><code>AnyInstanceRef</code> (spezialisiert <code>AtpInstanceRef</code>): Konkrete generische Instanzreferenz.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Aufzählung mit den Literalen <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>ARPackage</code> enthält per Komposition <code>+element</code> (<code>0..*</code>, <code>«atpSplitable,atpVariation»</code>) Instanzen von <code>PackageableElement</code>.\n</li><li><code>EvaluatedVariantSet</code> referenziert per gerichteter Assoziation <code>+evaluatedElement</code> (<code>0..*</code>) Elemente vom Typ <code>CollectableElement</code>.\n</li><li><code>Collection</code> referenziert per gerichteter Assoziation <code>+element</code> (<code>0..*</code>) und <code>+sourceElement</code> (<code>0..*</code>) Elemente vom Typ <code>Identifiable</code>.\n</li><li><code>Collection</code> enthält per Komposition <code>+collectedInstance</code> (<code>0..*</code>) und <code>+sourceInstance</code> (<code>0..*</code>) Instanzen von <code>AnyInstanceRef</code>.\n</li><li><code>Collection</code> besitzt abgeleitete Instanzreferenz-Assoziationen <code>«instanceRef» +collectedInstance</code> (<code>0..*</code>) und <code>«instanceRef» +sourceInstance</code> (<code>0..*</code>) auf <code>AtpFeature</code>.\n</li><li><code>AnyInstanceRef</code> referenziert <code>AtpFeature</code> über <code>+contextElement</code> (<code>0..* {subsets atpContextElement}</code>) sowie <code>+target</code> (<code>1 {redefines atpTarget}</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die strukturelle Organisation und Referenzierung von Elementen innerhalb der Paket- und Sammlungs-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für das flexible Sammeln und Nachverfolgen von Modellelementen und Instanzen. <code>Collection</code> unterstützt sowohl direkte Element-Referenzen (<code>Identifiable</code>) als auch modellübergreifende Instanzpfade (<code>AnyInstanceRef</code> auf <code>AtpFeature</code>) inklusive Quell- und Zielbeziehungen (<code>sourceElement</code>/<code>sourceInstance</code> vs. <code>element</code>/<code>collectedInstance</code>). Über <code>autoCollect</code> wird ein automatisches Sammelverhalten spezifiziert. <code>EvaluatedVariantSet</code> bindet Sammlungen und sammelbare Elemente an Freigabezustände (<code>approvalStatus</code>). Kompositionen an <code>ARPackage</code> unterliegen <code>«atpSplitable,atpVariation»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5fa9a4e36526b66d", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Es definiert die Metamodell-Struktur für AUTOSAR-Sammlungen (<code>Collection</code>), Instanzreferenzen (<code>AnyInstanceRef</code>) sowie Variantenmengen (<code>EvaluatedVariantSet</code>) im Kontext von Element- und Merkmalsreferenzierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Vererbung:</p>\n<ul class=\"fig-list\"><li><code>MultilanguageReferrable</code>: Basisklasse für mehrsprachig referenzierbare Elemente.\n</li><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für sammelbare Entitäten.\n</li><li><code>AtpFeature</code> (spezialisiert <code>Identifiable</code>): Repräsentiert referenzierbare Merkmale/Features im Metamodell.\n</li><li><code>PackageableElement</code> (spezialisiert <code>Identifiable</code>): Paketierbare Elemente.\n</li><li><code>ARPackage</code> (spezialisiert <code>CollectableElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>Identifiable</code>): Paketierungscontainer.\n</li><li><code>ARElement</code> (spezialisiert <code>PackageableElement</code>): Top-Level-AUTOSAR-Elemente.\n</li><li><code>Collection</code> (spezialisiert <code>ARElement</code>): Sammlungscontainer mit Attributen <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>.\n</li><li><code>EvaluatedVariantSet</code> (spezialisiert <code>ARElement</code>): Beschreibt evaluierte Varianten mit Attribut <code>approvalStatus: NameToken</code>.\n</li><li><code>AtpInstanceRef</code>: Abstrakte Basisklasse für Instanzreferenzen.\n</li><li><code>AnyInstanceRef</code> (spezialisiert <code>AtpInstanceRef</code>): Konkrete generische Instanzreferenz.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Aufzählung mit den Literalen <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>ARPackage</code> enthält per Komposition <code>+element</code> (<code>0..*</code>, <code>«atpSplitable,atpVariation»</code>) Instanzen von <code>PackageableElement</code>.\n</li><li><code>EvaluatedVariantSet</code> referenziert per gerichteter Assoziation <code>+evaluatedElement</code> (<code>0..*</code>) Elemente vom Typ <code>CollectableElement</code>.\n</li><li><code>Collection</code> referenziert per gerichteter Assoziation <code>+element</code> (<code>0..*</code>) und <code>+sourceElement</code> (<code>0..*</code>) Elemente vom Typ <code>Identifiable</code>.\n</li><li><code>Collection</code> enthält per Komposition <code>+collectedInstance</code> (<code>0..*</code>) und <code>+sourceInstance</code> (<code>0..*</code>) Instanzen von <code>AnyInstanceRef</code>.\n</li><li><code>Collection</code> besitzt abgeleitete Instanzreferenz-Assoziationen <code>«instanceRef» +collectedInstance</code> (<code>0..*</code>) und <code>«instanceRef» +sourceInstance</code> (<code>0..*</code>) auf <code>AtpFeature</code>.\n</li><li><code>AnyInstanceRef</code> referenziert <code>AtpFeature</code> über <code>+contextElement</code> (<code>0..* {subsets atpContextElement}</code>) sowie <code>+target</code> (<code>1 {redefines atpTarget}</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die strukturelle Organisation und Referenzierung von Elementen innerhalb der Paket- und Sammlungs-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für das flexible Sammeln und Nachverfolgen von Modellelementen und Instanzen. <code>Collection</code> unterstützt sowohl direkte Element-Referenzen (<code>Identifiable</code>) als auch modellübergreifende Instanzpfade (<code>AnyInstanceRef</code> auf <code>AtpFeature</code>) inklusive Quell- und Zielbeziehungen (<code>sourceElement</code>/<code>sourceInstance</code> vs. <code>element</code>/<code>collectedInstance</code>). Über <code>autoCollect</code> wird ein automatisches Sammelverhalten spezifiziert. <code>EvaluatedVariantSet</code> bindet Sammlungen und sammelbare Elemente an Freigabezustände (<code>approvalStatus</code>). Kompositionen an <code>ARPackage</code> unterliegen <code>«atpSplitable,atpVariation»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-698e33d3f1698f87", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Es definiert die Metamodell-Struktur für AUTOSAR-Sammlungen (<code>Collection</code>), Instanzreferenzen (<code>AnyInstanceRef</code>) sowie Variantenmengen (<code>EvaluatedVariantSet</code>) im Kontext von Element- und Merkmalsreferenzierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Vererbung:</p>\n<ul class=\"fig-list\"><li><code>MultilanguageReferrable</code>: Basisklasse für mehrsprachig referenzierbare Elemente.\n</li><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für sammelbare Entitäten.\n</li><li><code>AtpFeature</code> (spezialisiert <code>Identifiable</code>): Repräsentiert referenzierbare Merkmale/Features im Metamodell.\n</li><li><code>PackageableElement</code> (spezialisiert <code>Identifiable</code>): Paketierbare Elemente.\n</li><li><code>ARPackage</code> (spezialisiert <code>CollectableElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>Identifiable</code>): Paketierungscontainer.\n</li><li><code>ARElement</code> (spezialisiert <code>PackageableElement</code>): Top-Level-AUTOSAR-Elemente.\n</li><li><code>Collection</code> (spezialisiert <code>ARElement</code>): Sammlungscontainer mit Attributen <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>.\n</li><li><code>EvaluatedVariantSet</code> (spezialisiert <code>ARElement</code>): Beschreibt evaluierte Varianten mit Attribut <code>approvalStatus: NameToken</code>.\n</li><li><code>AtpInstanceRef</code>: Abstrakte Basisklasse für Instanzreferenzen.\n</li><li><code>AnyInstanceRef</code> (spezialisiert <code>AtpInstanceRef</code>): Konkrete generische Instanzreferenz.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Aufzählung mit den Literalen <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>ARPackage</code> enthält per Komposition <code>+element</code> (<code>0..*</code>, <code>«atpSplitable,atpVariation»</code>) Instanzen von <code>PackageableElement</code>.\n</li><li><code>EvaluatedVariantSet</code> referenziert per gerichteter Assoziation <code>+evaluatedElement</code> (<code>0..*</code>) Elemente vom Typ <code>CollectableElement</code>.\n</li><li><code>Collection</code> referenziert per gerichteter Assoziation <code>+element</code> (<code>0..*</code>) und <code>+sourceElement</code> (<code>0..*</code>) Elemente vom Typ <code>Identifiable</code>.\n</li><li><code>Collection</code> enthält per Komposition <code>+collectedInstance</code> (<code>0..*</code>) und <code>+sourceInstance</code> (<code>0..*</code>) Instanzen von <code>AnyInstanceRef</code>.\n</li><li><code>Collection</code> besitzt abgeleitete Instanzreferenz-Assoziationen <code>«instanceRef» +collectedInstance</code> (<code>0..*</code>) und <code>«instanceRef» +sourceInstance</code> (<code>0..*</code>) auf <code>AtpFeature</code>.\n</li><li><code>AnyInstanceRef</code> referenziert <code>AtpFeature</code> über <code>+contextElement</code> (<code>0..* {subsets atpContextElement}</code>) sowie <code>+target</code> (<code>1 {redefines atpTarget}</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die strukturelle Organisation und Referenzierung von Elementen innerhalb der Paket- und Sammlungs-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für das flexible Sammeln und Nachverfolgen von Modellelementen und Instanzen. <code>Collection</code> unterstützt sowohl direkte Element-Referenzen (<code>Identifiable</code>) als auch modellübergreifende Instanzpfade (<code>AnyInstanceRef</code> auf <code>AtpFeature</code>) inklusive Quell- und Zielbeziehungen (<code>sourceElement</code>/<code>sourceInstance</code> vs. <code>element</code>/<code>collectedInstance</code>). Über <code>autoCollect</code> wird ein automatisches Sammelverhalten spezifiziert. <code>EvaluatedVariantSet</code> bindet Sammlungen und sammelbare Elemente an Freigabezustände (<code>approvalStatus</code>). Kompositionen an <code>ARPackage</code> unterliegen <code>«atpSplitable,atpVariation»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8b1fe3205b060c3b", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Es definiert die Metamodell-Struktur für AUTOSAR-Sammlungen (<code>Collection</code>), Instanzreferenzen (<code>AnyInstanceRef</code>) sowie Variantenmengen (<code>EvaluatedVariantSet</code>) im Kontext von Element- und Merkmalsreferenzierungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Entitäten und Vererbung:</p>\n<ul class=\"fig-list\"><li><code>MultilanguageReferrable</code>: Basisklasse für mehrsprachig referenzierbare Elemente.\n</li><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (spezialisiert <code>Identifiable</code>): Abstrakte Basisklasse für sammelbare Entitäten.\n</li><li><code>AtpFeature</code> (spezialisiert <code>Identifiable</code>): Repräsentiert referenzierbare Merkmale/Features im Metamodell.\n</li><li><code>PackageableElement</code> (spezialisiert <code>Identifiable</code>): Paketierbare Elemente.\n</li><li><code>ARPackage</code> (spezialisiert <code>CollectableElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>Identifiable</code>): Paketierungscontainer.\n</li><li><code>ARElement</code> (spezialisiert <code>PackageableElement</code>): Top-Level-AUTOSAR-Elemente.\n</li><li><code>Collection</code> (spezialisiert <code>ARElement</code>): Sammlungscontainer mit Attributen <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>.\n</li><li><code>EvaluatedVariantSet</code> (spezialisiert <code>ARElement</code>): Beschreibt evaluierte Varianten mit Attribut <code>approvalStatus: NameToken</code>.\n</li><li><code>AtpInstanceRef</code>: Abstrakte Basisklasse für Instanzreferenzen.\n</li><li><code>AnyInstanceRef</code> (spezialisiert <code>AtpInstanceRef</code>): Konkrete generische Instanzreferenz.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Aufzählung mit den Literalen <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li></ul>\n<p class=\"fig-p\">Beziehungen und Assoziationen:</p>\n<ul class=\"fig-list\"><li><code>ARPackage</code> enthält per Komposition <code>+element</code> (<code>0..*</code>, <code>«atpSplitable,atpVariation»</code>) Instanzen von <code>PackageableElement</code>.\n</li><li><code>EvaluatedVariantSet</code> referenziert per gerichteter Assoziation <code>+evaluatedElement</code> (<code>0..*</code>) Elemente vom Typ <code>CollectableElement</code>.\n</li><li><code>Collection</code> referenziert per gerichteter Assoziation <code>+element</code> (<code>0..*</code>) und <code>+sourceElement</code> (<code>0..*</code>) Elemente vom Typ <code>Identifiable</code>.\n</li><li><code>Collection</code> enthält per Komposition <code>+collectedInstance</code> (<code>0..*</code>) und <code>+sourceInstance</code> (<code>0..*</code>) Instanzen von <code>AnyInstanceRef</code>.\n</li><li><code>Collection</code> besitzt abgeleitete Instanzreferenz-Assoziationen <code>«instanceRef» +collectedInstance</code> (<code>0..*</code>) und <code>«instanceRef» +sourceInstance</code> (<code>0..*</code>) auf <code>AtpFeature</code>.\n</li><li><code>AnyInstanceRef</code> referenziert <code>AtpFeature</code> über <code>+contextElement</code> (<code>0..* {subsets atpContextElement}</code>) sowie <code>+target</code> (<code>1 {redefines atpTarget}</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Es beschreibt die strukturelle Organisation und Referenzierung von Elementen innerhalb der Paket- und Sammlungs-Hierarchie.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Vorgabe für das flexible Sammeln und Nachverfolgen von Modellelementen und Instanzen. <code>Collection</code> unterstützt sowohl direkte Element-Referenzen (<code>Identifiable</code>) als auch modellübergreifende Instanzpfade (<code>AnyInstanceRef</code> auf <code>AtpFeature</code>) inklusive Quell- und Zielbeziehungen (<code>sourceElement</code>/<code>sourceInstance</code> vs. <code>element</code>/<code>collectedInstance</code>). Über <code>autoCollect</code> wird ein automatisches Sammelverhalten spezifiziert. <code>EvaluatedVariantSet</code> bindet Sammlungen und sammelbare Elemente an Freigabezustände (<code>approvalStatus</code>). Kompositionen an <code>ARPackage</code> unterliegen <code>«atpSplitable,atpVariation»</code>.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8465e0c81a3a105e", "to": "FIG-2832bafdff706200", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>Collection</code>: Attribute <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code> hinzugefügt.\n</li><li>Klasse <code>Collection</code>: Assoziation <code>+sourceElement</code> (Multiplizität <code>0..*</code>) zu <code>Identifiable</code> ergänzt.\n</li><li>Klasse <code>Collection</code>: Kompositionen <code>+collectedInstance</code> (<code>0..*</code>) und <code>+sourceInstance</code> (<code>0..*</code>) auf <code>AnyInstanceRef</code> ergänzt.\n</li><li>Klasse <code>Collection</code>: Assoziation <code>+element</code> (<code>0..*</code>) verweist neu direkt auf <code>Identifiable</code> (zuvor auf <code>CollectableElement</code>).\n</li><li>Klasse <code>Collection</code>: Assoziation <code>+arPackage</code> (<code>0..*</code>) zu <code>ARPackage</code> entfernt.\n</li><li>Neue Klasse <code>EvaluatedVariantSet</code> eingeführt (erbt von <code>ARElement</code>), mit Attribut <code>approvalStatus: NameToken</code> sowie Assoziation <code>+evaluatedElement</code> (<code>0..*</code>) auf <code>CollectableElement</code>.\n</li><li>Neue Klasse <code>AnyInstanceRef</code> (Spezialisierung von <code>AtpInstanceRef</code>) eingeführt mit Assoziationen <code>+contextElement</code> (<code>0..* {subsets atpContextElement}</code>) und <code>+target</code> (<code>1 {redefines atpTarget}</code>) auf <code>AtpFeature</code>.\n</li><li>Neue abgeleitete Assoziationen <code>«instanceRef» +collectedInstance</code> (<code>0..*</code>) und <code>«instanceRef» +sourceInstance</code> (<code>0..*</code>) von <code>Collection</code> auf <code>AtpFeature</code> eingeführt.\n</li><li>Neue Enumeration <code>AutoCollectEnum</code> eingeführt mit den Literalen <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li><li>Neue abstrakte Basisklasse <code>AtpFeature</code> eingeführt (erbt von <code>Identifiable</code>).\n</li><li>Klasse <code>Identifiable</code>: Erbt von <code>MultilanguageReferrable</code>; Attribute <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code> hinzugefügt.\n</li><li>Vererbungsbeziehungen: <code>PackageableElement</code> erbt nun direkt von <code>Identifiable</code>.\n</li><li>Stereotype / Präfixe: Paket-Präfixe <code>ARPackage::</code> an <code>ARPackage</code>, <code>PackageableElement</code> und <code>ARElement</code> entfernt.\n</li></ul>"}, {"from": "FIG-2832bafdff706200", "to": "FIG-5fa9a4e36526b66d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5fa9a4e36526b66d", "to": "FIG-698e33d3f1698f87", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-698e33d3f1698f87", "to": "FIG-8b1fe3205b060c3b", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Klassen <code>Identifiable</code> und <code>Collection</code>: Leerzeichen vor den Doppelpunkten bei Attributdeklarationen entfernt (z. B. <code>category: CategoryString</code> statt <code>category :CategoryString</code>).\n</li></ul>"}]};
